VALUES ('TensorLBM','m15212 REPRO-LBM-GUO2002',15271,2,'{"scope": "m15212 REPRO-LBM-GUO2002", "repo": "TensorLBM", "subject_mission": 15212, "subject_status": "succeeded (auto-approved dev_acceptance)", "audit_mission": 15271, "verdict_by": "board-audit", "declared_level": 2, "level_rationale": "L2 独立功能实现：真代码（入口 scripts/repro_guo2002_dhc.py 输入 Ra/ny/Pr/ma_max → 调 tensorlbm.rb_convection_validation.run_to_steady → 输出 Nu/步数/无量纲/末态场 npz），本审计独立复跑两档网格均逐位复现（Nu=1.0891168713569641 / 1.1032668749491374，bitwise True）；有 pytest 6 passed。不到 L3：交付代码未进 TensorLBM main（merge-base --is-ancestor 01a87bfa HEAD → NOT_MERGED；main 树内 grep return_fields 命中 0），无主求解器/平台侧调用方（integration_callers 为空），不满足 gate 的 L3 grep 复核。不到 L4：基准不完整（Ra=1e5 超差 8.93%，容差<5%），6 档数据中 4 档为前作归档引用（steps/ma/tau_f 全 null，非本单实跑），Ra=1e4/1e5 无末态场与等温线图，且 tensor_benchmark_cases 对 anchor REPRO-LBM-GUO2002 零行（无机器裁判行）。", "impl_files": ["docs/board_audit/m15271/refs/impl/repro_guo2002_dhc.py", "docs/board_audit/m15271/refs/impl/repro_guo2002_ladder.py", "docs/board_audit/m15271/refs/impl/repro_guo2002_analysis.py", "docs/board_audit/m15271/refs/impl/test_repro_guo2002_dhc.py", "docs/board_audit/m15271/refs/impl/rb_convection_validation.py"], "entry": "docs/board_audit/m15271/refs/impl/repro_guo2002_dhc.py", "run_artifacts": ["docs/board_audit/m15271/refs/artifacts/runs/summary.json", "docs/board_audit/m15271/refs/artifacts/runs/ladder_summary.json", "docs/board_audit/m15271/refs/artifacts/runs/ra1000_ny32_ma0.1.json", "docs/board_audit/m15271/refs/artifacts/runs/ra1000_ny32_ma0.1.npz", "docs/board_audit/m15271/refs/artifacts/runs/ra1000_ny64_ma0.1.json", "docs/board_audit/m15271/refs/artifacts/runs/ra1000_ny64_ma0.1.npz", "docs/board_audit/m15271/refs/artifacts/runs/ra10000_ny128_ma0.2.json", "docs/board_audit/m15271/refs/artifacts/runs/ra100000_ny128_ma0.2.json", "docs/board_audit/m15271/refs/artifacts/figures/fig1_isoterms_dhc.png", "docs/board_audit/m15271/refs/artifacts/figures/fig2_nu_vs_ra.png", "docs/board_audit/m15271/re